"""Tests for the scoped deletion-tombstone ledger.

Covers record_deletion_tombstones / finish_scoped_claim /
get_deletion_tombstones on the storage layer only: lease-gated
registration, item validation, idempotent replay, operation-number and
outcome conflicts, coverage-gated completion, first-result replay,
persistence across rebuilds, corruption handling and the no-leak
guarantees. These entry points are deliberately not exposed over HTTP.
"""

import hashlib
import os
import sqlite3
import struct
import tempfile
import unittest

from forgetting_evidence.requests import (
    ClaimConflict,
    RequestNotFound,
    RequestStore,
    TombstoneConflict,
    TombstoneUnavailable,
)


def _digest(seed):
    return hashlib.sha256(seed.encode("utf-8")).hexdigest()


def _item(scope, operation, adapter="adapter-1", outcome="deleted", proof=None):
    return {
        "adapter_id": adapter,
        "scope": scope,
        "operation_id": operation,
        "outcome": outcome,
        "proof_digest": proof if proof is not None else _digest(operation),
    }


def _expected_digest(items):
    digest = hashlib.sha256()
    rows = sorted(
        (i["scope"], i["operation_id"], i["adapter_id"], i["outcome"], i["proof_digest"])
        for i in items
    )
    for row in rows:
        for field in row:
            encoded = field.encode("utf-8")
            digest.update(struct.pack(">Q", len(encoded)))
            digest.update(encoded)
    return digest.hexdigest()


class _StoreCase(unittest.TestCase):
    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.db_path = os.path.join(self._tmp.name, "nested", "evidence.db")

    def tearDown(self):
        self._tmp.cleanup()

    def _store(self):
        return RequestStore(self.db_path)

    def _submit(self, store, tenant="tenant-a", key="key-1", scopes=("email", "profile")):
        return store.submit(tenant, "subject-1", list(scopes), key)

    def _claim(self, store, tenant="tenant-a", lease_seconds=60):
        claim = store.claim_next(tenant, "worker-1", lease_seconds)
        self.assertIsNotNone(claim)
        return claim

    def _claimed(self, scopes=("email", "profile"), tenant="tenant-a", key="key-1"):
        store = self._store()
        receipt = self._submit(store, tenant=tenant, key=key, scopes=scopes)
        claim = store.claim_next(tenant, "worker-1", 60)
        return store, receipt, claim


class RecordTest(_StoreCase):
    def test_record_and_get_roundtrip(self):
        store, receipt, claim = self._claimed()
        items = [
            _item("profile", "op-2", adapter="adapter-b", outcome="absent"),
            _item("email", "op-1", adapter="adapter-a"),
        ]
        record = store.record_deletion_tombstones(
            "tenant-a", receipt["request_id"], claim["claim_token"], items
        )
        self.assertEqual(
            set(record), {"request_id", "recorded_at", "evidence_digest"}
        )
        self.assertEqual(record["request_id"], receipt["request_id"])
        self.assertEqual(record["evidence_digest"], _expected_digest(items))

        got = store.get_deletion_tombstones("tenant-a", receipt["request_id"])
        self.assertEqual(
            set(got), {"request_id", "tombstones", "recorded_at", "evidence_digest"}
        )
        # Ordered by normalized scope, then adapter_id.
        self.assertEqual(
            [(t["scope"], t["adapter_id"]) for t in got["tombstones"]],
            [("email", "adapter-a"), ("profile", "adapter-b")],
        )
        self.assertEqual(got["recorded_at"], record["recorded_at"])
        self.assertEqual(got["evidence_digest"], record["evidence_digest"])
        for entry in got["tombstones"]:
            self.assertEqual(
                set(entry),
                {
                    "adapter_id",
                    "scope",
                    "operation_id",
                    "outcome",
                    "proof_digest",
                    "recorded_at",
                },
            )

    def test_get_empty_ledger(self):
        store, receipt, _ = self._claimed()
        got = store.get_deletion_tombstones("tenant-a", receipt["request_id"])
        self.assertEqual(got["tombstones"], [])
        self.assertIsNone(got["recorded_at"])
        self.assertIsNone(got["evidence_digest"])

    def test_replay_same_list_returns_first_settlement(self):
        store, receipt, claim = self._claimed()
        items = [_item("email", "op-1"), _item("profile", "op-2")]

import json
import signal
import sys

from .httpapi import (
    AuthConfigError,
    DeferredRequestStore,
    build_server,
    load_auth_config,
)

_USAGE = "usage: python -m forgetting_evidence health"
_SERVE_USAGE = (
    "usage: python -m forgetting_evidence serve <database> <address> <port>\n"
    "       python -m forgetting_evidence serve --db <database> "
    "--host <address> --port <port> [--auth-file <auth-config>]"
)

_FLAG_ALIASES = {
    "--db": "db",
    "--database": "db",
    "--host": "host",
    "--address": "host",
    "--bind": "host",
    "--port": "port",
    "--auth-file": "auth_file",
}
_POSITIONAL_FIELDS = ("db", "host", "port")


def _parse_serve_args(args: list[str]) -> dict[str, str] | None:
    values: dict[str, str] = {}
    positionals: list[str] = []
    index = 0
    while index < len(args):
        token = args[index]
        if "=" in token and token.split("=", 1)[0] in _FLAG_ALIASES:
            name, value = token.split("=", 1)
            field = _FLAG_ALIASES[name]
            if field in values or value == "":
                return None
            values[field] = value
        elif token in _FLAG_ALIASES:
            field = _FLAG_ALIASES[token]
            if field in values or index + 1 >= len(args):
                return None
            values[field] = args[index + 1]
            index += 1
        elif token.startswith("--"):
            return None
        else:
            positionals.append(token)
        index += 1
    if positionals and values:
        # Avoid ambiguity when both styles are mixed.
        return None
    if positionals:
        if len(positionals) != 3:
            return None
        values = dict(zip(_POSITIONAL_FIELDS, positionals))
    missing = [field for field in _POSITIONAL_FIELDS if not values.get(field)]
    if missing:
        return None
    return values


def _run_serve(args: list[str]) -> int:
    parsed = _parse_serve_args(args)
    if parsed is None:
        print(_SERVE_USAGE, file=sys.stderr)
        return 2
    try:
        port = int(parsed["port"])
    except ValueError:
        print(_SERVE_USAGE, file=sys.stderr)
        return 2
    if not 1 <= port <= 65535:
        print(_SERVE_USAGE, file=sys.stderr)
        return 2

    # The auth configuration is read and validated exactly once, before
    # the port is bound. A missing/unreadable file or any non-compliant
    # configuration refuses startup: no socket is opened and the process
    # exits with status 2 and the fixed marker only -- the path, tokens
    # and configuration content are never printed.
    auth = None
    if parsed.get("auth_file"):
        try:
            auth = load_auth_config(parsed["auth_file"])
        except AuthConfigError:
            print("auth_config_invalid", file=sys.stderr)
            return 2

    # The store opens (creating the file and required tables) at startup.
    # If the database cannot be created the service still binds: business
    # requests then answer 503 storage_unavailable and the store retries
    # initialization on the next request so a repaired path self-heals.
    store = DeferredRequestStore(parsed["db"])
    try:
        server = build_server(store, parsed["host"], port, auth)
    except OSError:
        print("address_in_use", file=sys.stderr)
        return 1

    def _stop(_signum, _frame):
        raise KeyboardInterrupt

    previous_sigterm = signal.signal(signal.SIGTERM, _stop)
    try:
        try:
            server.serve_forever()
        except KeyboardInterrupt:
            pass
        finally:
            server.server_close()
    finally:
        signal.signal(signal.SIGTERM, previous_sigterm)
    return 0


def main(argv: list[str] | None = None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    if args == ["health"]:
        print(json.dumps({"service": "forgetting-evidence", "status": "ok"}, sort_keys=True))
        return 0
    if args and args[0] == "serve":
        return _run_serve(args[1:])
    print(_USAGE, file=sys.stderr)
    return 2


if __name__ == "__main__":
    raise SystemExit(main())

